fn less(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Assuming `a.len() == b.len()`, we can safely zip them.
    a.into_iter()
     .zip(b.into_iter())
     .map(|(x, y)| x < y)
     .collect()
}